@Test
  public void explainThrowable4() {
    String msg = Throwables2.explain(
        new RuntimeException("foo",
            new Exception("bar",
                new Exception("baz")
            )
        )
    );
    log(msg);
    assertThat(msg, is("java.lang.RuntimeException: foo, caused by: java.lang.Exception: bar, caused by: java.lang.Exception: baz"));
  }

